  /* 0x06 */ "+CALL",
  /* 0x07 */ "*ALL",
  /* 0x08 */ "FMT",
  /* 0x09 */ "H",
  /* 0x0a */ "GT",
  /* 0x0b */ "EXIT",
  /* 0x0c */ "CARRY",
  /* 0x0d */ "OVF",
  /* 0x0e */ "*PARSE",
  /* 0x0f */ "*XML",
  /* 0x10 */ "CONT",
  /* 0x11 */ "EXEC",
  /* 0x12 */ "RTNB",
  /* 0x13 */ "RTGR",
  /* 0x14 */ "XG-4",
  /* 0x15 */ "XG-5",
  /* 0x16 */ "XG-6",
  /* 0x17 */ "XG-7",
  /* 0x18 */ "XG-8",
