  /* 0x1c */ "XG-C",
  /* 0x1d */ "XG-D",
  /* 0x1e */ "XG-E",
  /* 0x1f */ "XG-$",
};

static const char *type4_ops[] = {
  /* 0x40-0x5f */ "BR",
  /* 0x60-0x7f */ "BS",
};

static const char *type5_ops[] = {
  /* 0x80-0x81 */ "ABS",
  /* 0x82-0x83 */ "NEG",
