    "LBLT": (0x10, 0x2D),
    "LBGT": (0x10, 0x2E),
    "LBLE": (0x10, 0x2F),
    "LBRA": (0x00, 0x16),
    "LBSR": (0x00, 0x17),
}

LEA_BASE: dict[str, int] = {
    "LEAX": 0x30,
    "LEAY": 0x31,
    "LEAS": 0x32,
    "LEAU": 0x33,
}

STACK_BASE: dict[str, int] = {
    "PSHS": 0x34,
    "PULS": 0x35,
    "PSHU": 0x36,
    "PULU": 0x37,
}

INHERENT: dict[str, tuple[int, int]] = {
    "NOP":  (0x00, 0x12),
    "SYNC": (0x00, 0x13),
    "DAA":  (0x00, 0x19),
    "SEX":  (0x00, 0x1D),
    "RTS":  (0x00, 0x39),
    "ABX":  (0x00, 0x3A),
    "RTI":  (0x00, 0x3B),
    "MUL":  (0x00, 0x3D),
    "SWI":  (0x00, 0x3F),
    "SWI2": (0x10, 0x3F),
    "SWI3": (0x11, 0x3F),
}

